const body = $input.first().json.body || $input.first().json;
const name = body.name || "Calzado Flores";
const category = body.category || "calzado";
const price = body.price ? `Bs. ${body.price}` : "Precio a consultar";
const imageUrl = body.imageUrl || "";

const promptText = `Sos el director de arte fotográfico y estratega de contenido de FLORES (marca boliviana de calzado femenino de lujo, estética brutalista editorial, acento carmín #9B1C1C, sin amarillo, sobrio, elegante y transparente).

Producto: "${name}"
Categoría: "${category}"
Precio: ${price}
Foto de referencia: ${imageUrl}

Genera 2 prompts en INGLÉS altamente técnicos para generadores de imágenes (evitando palabras cliché como "photorealistic 8k unreal engine", y usando términos fotográficos reales):

1. "prompt_studio": Enfocado en el calzado como pieza de diseño/escultura en estudio. Pedestal de hormigón brutalista o piedra volcánica oscura, iluminación suave de softbox lateral, tenue acento carmín en el borde, lente de 85mm f/2.8, textura realista de cuero genuino, composición limpia para revista Vogue. (Este prompt se usará para generar el póster en FLUX).
2. "prompt_lifestyle": Enfocado en modelo humana vistiendo el calzado en un entorno de alta costura o arquitectónico. Plano de cuerpo entero o detalle tres cuartos, vestimenta minimalista sastre monocromática, iluminación natural suave, postura elegante, interacción perfecta del calzado con el suelo. (Ideal para Nano Banana con imagen de referencia).

Y 3 copies en español boliviano neutro:
- "tiktok": Texto magnético de 1 a 2 líneas sin urgencia falsa.
- "instagram": Caption editorial con tono de lujo accesible y llamado a la acción.
- "whatsapp": Mensaje de difusión con precio y link de consulta.

Devuelve ÚNICAMENTE un objeto JSON válido con esta estructura exacta (sin markdown ni texto extra):
{
  "prompt_studio": "...",
  "prompt_lifestyle": "...",
  "tiktok": "...",
  "instagram": "...",
  "whatsapp": "..."
}`;

return {
  name,
  category,
  price,
  imageUrl,
  geminiPayload: {
    contents: [
      {
        parts: [
          { text: promptText }
        ]
      }
    ]
  }
};

const prev = $node['Preparar Prompt'].json;
const geminiRes = $input.first().json;

let cleanText = '';
try {
  cleanText = geminiRes.candidates[0].content.parts[0].text;
} catch (e) {
  cleanText = '{}';
}

cleanText = cleanText.trim();
if (cleanText.startsWith('```json')) cleanText = cleanText.substring(7);
if (cleanText.startsWith('```')) cleanText = cleanText.substring(3);
if (cleanText.endsWith('```')) cleanText = cleanText.substring(0, cleanText.length - 3);
cleanText = cleanText.trim();

let parsed = {};
try {
  parsed = JSON.parse(cleanText);
} catch (e) {
  parsed = {
    prompt_studio: `Editorial commercial footwear photography of ${prev.name}, displayed on a dark raw concrete pedestal, studio lighting with subtle crimson edge glow, 85mm lens f/2.8, authentic leather texture, Vogue aesthetic`,
    prompt_lifestyle: `Full-length fashion editorial shot of an elegant model wearing ${prev.name}, monochromatic minimalist suit, brutalist architectural interior, soft natural lighting`,
    tiktok: `Descubre la nueva silueta ${prev.name} en Flores Store.`,
    instagram: `${prev.name} — Calzado con diseño atemporal y stock real en Bolivia. Precio: ${prev.price}`,
    whatsapp: `¡Nuevo ingreso! ${prev.name} a ${prev.price}. Escríbenos para consultar tallas disponibles.`
  };
}

const fluxEncoded = encodeURIComponent(parsed.prompt_studio || 'luxury footwear poster');
const randomSeed = Math.floor(Math.random() * 900000) + 100000;
const pollinationsUrl = `https://image.pollinations.ai/prompt/${fluxEncoded}?width=800&height=1000&model=flux-realism&nologo=true&seed=${randomSeed}`;

return {
  name: prev.name,
  category: prev.category,
  price: prev.price,
  imageUrl: prev.imageUrl,
  prompt_studio: parsed.prompt_studio,
  prompt_lifestyle: parsed.prompt_lifestyle,
  tiktok: parsed.tiktok,
  instagram: parsed.instagram,
  whatsapp: parsed.whatsapp,
  poster_url: pollinationsUrl
};

